// Purpose: Parse the complete AI Health OS Final Report into one canonical object.
// Supports objects, one-item arrays, JSON strings, Markdown-fenced JSON, and common n8n wrappers.
const input = $input.first()?.json || {};
function stripFence(value) {
  if (typeof value !== 'string') return value;
  return value.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
}
function parseMaybe(value) {
  const clean = stripFence(value);
  return typeof clean === 'string' ? JSON.parse(clean) : clean;
}
function unwrap(value) {
  let current = value;
  if (Array.isArray(current) && current.length === 1) current = current[0];
  if (current && typeof current === 'object' && current.json && Object.keys(current).length <= 3) current = current.json;
  if (current && typeof current === 'object' && current.final_report_json !== undefined) current = current.final_report_json;
  else if (current && typeof current === 'object' && current.final_report !== undefined) current = current.final_report;
  else if (current && typeof current === 'object' && current.data && !current.agent_results) current = current.data;
  else if (current && typeof current === 'object' && current.output && !current.agent_results) current = current.output;
  current = parseMaybe(current);
  if (Array.isArray(current) && current.length === 1) current = current[0];
  if (current && typeof current === 'object' && current.json && Object.keys(current).length <= 3) current = current.json;
  return current;
}
try {
  const source = input.final_report_json ?? input.final_report ?? input.payload ?? input;
  const finalReport = unwrap(parseMaybe(source));
  if (!finalReport || typeof finalReport !== 'object' || Array.isArray(finalReport)) throw new Error('Final Report must resolve to a JSON object.');
  return [{ json: { parse_success: true, parse_error: '', requested_model: String(input.video_model || input.model || finalReport.video_model || 'veo_3'), final_report: finalReport, raw_input: input } }];
} catch (error) {
  return [{ json: { parse_success: false, parse_error: `Final Report JSON parse failed: ${error.message}`, requested_model: String(input.video_model || input.model || 'veo_3'), final_report: {}, raw_input: input } }];
}

// Purpose: Validate the Master Final Report before any production prompts are generated.
// Validation is non-destructive and reports every missing requirement in one response.
const data = $input.first()?.json || {};
const report = data.final_report || {};
const results = report.agent_results || {};
const a3 = results.agent_3 || report.agent_3_output || {};
const a4 = results.agent_4 || report.agent_4_output || {};
const a5 = results.agent_5 || report.agent_5_output || {};
const a6 = results.agent_6 || report.agent_6_output || {};
function arrayAt(obj, keys) { for (const key of keys) if (Array.isArray(obj?.[key])) return obj[key]; return []; }
function text(value) { return String(value ?? '').trim(); }
const scripts = arrayAt(a3, ['scripts', 'script_results', 'results', 'records']);
const plans = arrayAt(a4, ['visual_plans', 'visual_projects', 'results', 'records']);
const voiceovers = arrayAt(a5, ['voiceover_packages', 'results', 'records']);
const publishing = Array.isArray(report.final_publishing_packages) ? report.final_publishing_packages : arrayAt(a6, ['publishing_packages', 'results', 'records']);
const script = scripts[0] || {};
const plan = plans[0] || {};
const voiceover = voiceovers[0] || {};
const scenes = arrayAt(plan, ['scenes', 'scene_plan', 'shot_list', 'shots']);
const errors = [];
const warnings = [];
if (!data.parse_success) errors.push(data.parse_error || 'Final Report could not be parsed.');
if (text(report.status).toLowerCase() !== 'success') errors.push('Final Report status must be success.');
if (!report.agent_results && !report.agent_3_output) errors.push('Preserved Agent outputs are missing.');
if (!text(report.topic || script.topic || script.source_title)) errors.push('Topic is missing.');
if (!text(report.product_name) && !text(publishing[0]?.product_name)) warnings.push('Product Name is empty; production can continue without product placement.');
if (!text(script.video_title || publishing[0]?.video_title)) errors.push('Video Title is missing.');
if (!text(script.hook)) errors.push('Hook is missing from Agent 3 output.');
if (!text(script.full_script || script.body)) errors.push('Full Script or script body is missing from Agent 3 output.');
if (!plans.length) errors.push('Agent 4 visual_plans[] is empty.');
if (!scenes.length) errors.push('Scene Plan / Shot List is empty.');
if (!text(voiceover.full_voiceover_script || voiceover.voiceover_script || voiceover.voiceover)) errors.push('Voiceover is missing from Agent 5 output.');
if (!text(voiceover.srt) && !arrayAt(voiceover, ['subtitle_segments', 'subtitles']).length) errors.push('Subtitles and SRT are missing from Agent 5 output.');
if (!publishing.length) errors.push('Publishing Package is missing from Agent 6 output.');
return [{ json: { ...data, validation_passed: errors.length === 0, validation_errors: errors, validation_warnings: warnings, source_counts: { scripts: scripts.length, visual_plans: plans.length, scenes: scenes.length, voiceover_packages: voiceovers.length, publishing_packages: publishing.length } } }];

// Purpose: Return a structured error when Final Report parsing or required-field validation fails.
// No prompts or files are generated on this branch.
const data = $input.first()?.json || {};
return [{ json: { workflow: 'AI Health OS Video Generator', version: '1.0', status: 'error', failed_step: data.parse_success ? 'Validate Input' : 'Parse Final Report', parse_error: data.parse_error || '', validation_errors: data.validation_errors || [], validation_warnings: data.validation_warnings || [], suggested_action: 'Provide the complete successful AI Health OS Final Report JSON with preserved Agent 3–6 outputs.', raw_input: data.raw_input || {} } }];

// Purpose: Extract production fields from preserved Agent 3–6 outputs into a stable internal contract.
// Agent outputs and Agent 6 publishing content are copied, never rewritten.
const data = $input.first()?.json || {};
const report = data.final_report || {};
const results = report.agent_results || {};
const a3 = results.agent_3 || report.agent_3_output || {};
const a4 = results.agent_4 || report.agent_4_output || {};
const a5 = results.agent_5 || report.agent_5_output || {};
const a6 = results.agent_6 || report.agent_6_output || {};
function arrayAt(obj, keys) { for (const key of keys) if (Array.isArray(obj?.[key])) return obj[key]; return []; }
function text(value) { return String(value ?? '').trim(); }
const script = arrayAt(a3, ['scripts', 'script_results', 'results', 'records'])[0] || {};
const visualPlan = arrayAt(a4, ['visual_plans', 'visual_projects', 'results', 'records'])[0] || {};
const voiceoverPackage = arrayAt(a5, ['voiceover_packages', 'results', 'records'])[0] || {};
const publishingPackage = (Array.isArray(report.final_publishing_packages) ? report.final_publishing_packages : arrayAt(a6, ['publishing_packages', 'results', 'records']))[0] || {};
const hook = text(script.hook);
const body = text(script.body || script.full_script || script.script);
const cta = text(script.cta);
const fullScript = text(script.full_script || [hook, body, cta].filter(Boolean).join(' '));
const scenePlan = arrayAt(visualPlan, ['scenes', 'scene_plan', 'shot_list', 'shots']);
return [{ json: { ...data, production_input: { source_workflow: text(report.workflow || 'AI Health OS Master Orchestrator'), source_master_run_id: text(report.master_run_id), topic: text(report.topic || script.topic || script.source_title), product_name: text(report.product_name || publishingPackage.product_name), target_platform: text(report.target_platform), target_audience: text(report.target_audience), language: text(report.language || 'en-US'), brand_tone: text(report.brand_tone), video_duration_seconds: Number(report.video_duration_seconds || voiceoverPackage.estimated_duration_seconds || 30), video_title: text(script.video_title || publishingPackage.video_title), hook, full_script: fullScript, scene_plan: scenePlan, visual_plan: visualPlan, visual_prompts: arrayAt(visualPlan, ['visual_prompts', 'image_prompts', 'video_prompts']), voiceover: text(voiceoverPackage.full_voiceover_script || voiceoverPackage.voiceover_script || voiceoverPackage.voiceover), voiceover_segments: arrayAt(voiceoverPackage, ['voiceover_segments', 'narration_segments']), subtitles: arrayAt(voiceoverPackage, ['subtitle_segments', 'subtitles']), subtitles_srt: text(voiceoverPackage.srt), publishing_package: publishingPackage } } }];

// Purpose: Build a completely model-independent Canonical Scene Specification.
// No provider names, provider parameters, or provider-specific syntax are introduced here.
const data = $input.first()?.json || {};
const input = data.production_input || {};
function text(value) { return String(value ?? '').trim(); }
function number(value, fallback) { const n = Number(value); return Number.isFinite(n) && n >= 0 ? n : fallback; }
function array(value) { return Array.isArray(value) ? value : []; }
const rawScenes = array(input.scene_plan);
const defaultDuration = rawScenes.length ? number(input.video_duration_seconds, 30) / rawScenes.length : number(input.video_duration_seconds, 30);
const scenes = rawScenes.map((scene, index) => {
  const camera = scene.camera && typeof scene.camera === 'object' ? scene.camera : {};
  const start = number(scene.start_time_seconds ?? scene.start_time ?? scene.start, index * defaultDuration);
  const duration = number(scene.duration_seconds ?? scene.duration, defaultDuration);
  const visualPrompt = text(scene.visual_prompt || scene.image_prompt || scene.video_prompt || scene.visual_description || scene.description);
  return {
    scene_id: text(scene.scene_id || scene.shot_id || `scene_${String(index + 1).padStart(3, '0')}`),
    scene_number: index + 1,
    start_time_seconds: start,
    duration_seconds: duration,
    narration: text(scene.narration || scene.voiceover || input.voiceover_segments[index]?.voiceover_text),
    subtitle: text(scene.subtitle || scene.subtitle_text || input.subtitles[index]?.text || input.subtitles[index]?.subtitle_text),
    visual_goal: text(scene.visual_goal || scene.section || scene.purpose),
    subject: text(scene.subject || 'the approved wellness subject'),
    action: text(scene.action || scene.visual_action),
    environment: text(scene.environment || scene.setting || scene.location),
    camera: {
      shot_type: text(camera.shot_type || scene.shot_type), angle: text(camera.angle || scene.camera_angle),
      movement: text(camera.movement || scene.camera_movement), lens: text(camera.lens || scene.lens)
    },
    lighting: text(scene.lighting), color_palette: text(scene.color_palette || scene.colors),
    composition: text(scene.composition || 'vertical 9:16 composition'),
    continuity_notes: text(scene.continuity_notes || scene.continuity),
    on_screen_text: text(scene.on_screen_text || scene.screen_text),
    requires_image_prompt: Boolean(scene.requires_image_prompt || scene.image_prompt || scene.reference_image_required),
    source_visual_prompt: visualPrompt,
    negative_constraints: array(scene.negative_constraints || scene.negative_prompt)
  };
});
return [{ json: { ...data, canonical_scene_specification_version: '1.0', canonical_scenes: scenes } }];

// Purpose: Generate provider-neutral cinematic prompts from canonical scenes.
// These prompts describe creative intent only; model adapters translate them into provider formats.
const data = $input.first()?.json || {};
const input = data.production_input || {};
function text(value, fallback = '') { const v = String(value ?? '').trim(); return v || fallback; }
const scenes = (data.canonical_scenes || []).map((scene) => {
  const camera = scene.camera || {};
  const parts = [
    `Scene ${scene.scene_number}, ${scene.duration_seconds} seconds, vertical 9:16 cinematic short-form video`,
    `${text(scene.subject, 'Approved wellness subject')} ${text(scene.action, 'shown naturally')}`,
    `environment: ${text(scene.environment, 'authentic calm wellness setting')}`,
    `visual intent: ${text(scene.visual_goal || scene.source_visual_prompt, 'clear educational lifestyle storytelling')}`,
    `camera: ${text(camera.shot_type, 'cinematic medium shot')}, ${text(camera.angle, 'natural eye-level angle')}, ${text(camera.movement, 'smooth controlled movement')}, ${text(camera.lens, 'natural cinematic depth of field')}`,
    `lighting: ${text(scene.lighting, 'soft motivated natural light')}`,
    `color palette: ${text(scene.color_palette, 'warm, calm, trustworthy natural tones')}`,
    `composition: ${text(scene.composition, 'clean vertical composition with mobile-safe framing')}`,
    `continuity: ${text(scene.continuity_notes, 'preserve subject, product, wardrobe, lighting, and spatial continuity')}`,
    scene.on_screen_text ? `reserve clean space for later overlay text: ${scene.on_screen_text}; do not render letters in generated footage` : 'do not render text in generated footage',
    'photorealistic details, believable motion, stable anatomy, coherent objects, polished commercial production quality',
    'educational wellness context only; no medical outcomes, treatment imagery, logos, or watermark'
  ];
  const negative = ['medical procedure imagery', 'disease-treatment claims', 'guaranteed outcomes', 'warped anatomy', 'extra fingers', 'duplicate objects', 'flicker', 'unreadable text', 'logos', 'watermark', ...(scene.negative_constraints || [])];
  return { ...scene, canonical_cinematic_prompt: parts.join('. ') + '.', canonical_negative_prompt: Array.from(new Set(negative.map(String))).join(', ') };
});
return [{ json: { ...data, canonical_scenes: scenes, canonical_prompt_count: scenes.length } }];

// Purpose: Normalize the requested provider and expose one routing value for the Model Adapter Layer.
// Upstream canonical scenes remain unchanged regardless of the selected provider.
const data = $input.first()?.json || {};
const raw = String(data.requested_model || 'veo_3').trim().toLowerCase().replace(/[\s-]+/g, '_');
const aliases = { veo: 'veo_3', veo3: 'veo_3', google_veo_3: 'veo_3', runwayml: 'runway', runway_gen4: 'runway', kling_ai: 'kling', hailuo_ai: 'hailuo' };
const selected = aliases[raw] || raw;
const supported = ['veo_3', 'runway', 'kling', 'hailuo'];
return [{ json: { ...data, selected_model: selected, adapter_supported: supported.includes(selected), available_adapters: supported } }];

// Purpose: Translate canonical scenes into Veo 3 prompt objects only.
// This adapter may be replaced without changing parsing, canonical scenes, QA, or exports.
const data = $input.first()?.json || {};
const prompts = (data.canonical_scenes || []).map((s) => ({ provider: 'veo_3', scene_id: s.scene_id, prompt: `${s.canonical_cinematic_prompt} Include synchronized natural ambient audio appropriate to the scene; no generated dialogue unless narration is explicitly requested.`, duration_seconds: s.duration_seconds, aspect_ratio: '9:16', audio_guidance: 'Natural scene ambience; voiceover is added in post-production.', negative_prompt: s.canonical_negative_prompt, canonical_prompt: s.canonical_cinematic_prompt }));
return [{ json: { ...data, model_adapter: 'veo_3', video_prompts: prompts } }];

// Purpose: Translate canonical scenes into Runway-oriented prompt objects only.
// Canonical creative intent is preserved while provider controls stay isolated here.
const data = $input.first()?.json || {};
const prompts = (data.canonical_scenes || []).map((s) => ({ provider: 'runway', scene_id: s.scene_id, text_prompt: s.canonical_cinematic_prompt, duration_seconds: s.duration_seconds, ratio: '9:16', camera_control: s.camera?.movement || '', reference_mode: s.requires_image_prompt ? 'image_to_video' : 'text_to_video', negative_prompt: s.canonical_negative_prompt, canonical_prompt: s.canonical_cinematic_prompt }));
return [{ json: { ...data, model_adapter: 'runway', video_prompts: prompts } }];

// Purpose: Translate canonical scenes into Kling-oriented prompt objects only.
// No upstream extraction or canonical scene field depends on Kling.
const data = $input.first()?.json || {};
const prompts = (data.canonical_scenes || []).map((s) => ({ provider: 'kling', scene_id: s.scene_id, positive_prompt: s.canonical_cinematic_prompt, negative_prompt: s.canonical_negative_prompt, duration_seconds: s.duration_seconds, aspect_ratio: '9:16', motion_guidance: s.camera?.movement || 'smooth natural motion', creativity_mode: 'balanced', canonical_prompt: s.canonical_cinematic_prompt }));
return [{ json: { ...data, model_adapter: 'kling', video_prompts: prompts } }];

// Purpose: Translate canonical scenes into Hailuo-oriented prompt objects only.
// Provider-specific motion and framing instructions are confined to this adapter.
const data = $input.first()?.json || {};
const prompts = (data.canonical_scenes || []).map((s) => ({ provider: 'hailuo', scene_id: s.scene_id, prompt: s.canonical_cinematic_prompt, negative_prompt: s.canonical_negative_prompt, duration_seconds: s.duration_seconds, aspect_ratio: '9:16', motion: s.camera?.movement || 'stable cinematic movement', first_frame_reference_recommended: Boolean(s.requires_image_prompt), canonical_prompt: s.canonical_cinematic_prompt }));
return [{ json: { ...data, model_adapter: 'hailuo', video_prompts: prompts } }];

// Purpose: Fail safely when no installed Model Adapter matches the requested provider.
// The response lists supported adapters and does not generate partial files.
const data = $input.first()?.json || {};
return [{ json: { workflow: 'AI Health OS Video Generator', version: '1.0', status: 'error', failed_step: 'Model Adapter Layer', requested_model: data.selected_model || data.requested_model || '', available_adapters: data.available_adapters || ['veo_3', 'runway', 'kling', 'hailuo'], error_message: 'No installed Model Adapter matches the requested video model.', suggested_action: 'Choose a supported adapter or add a new isolated adapter node that consumes the Canonical Scene Specification.' } }];

// Purpose: Build optional model-independent still-image/reference-frame prompts for each scene.
// Image prompts remain separate from video-provider adapters and preserve scene alignment.
const data = $input.first()?.json || {};
const prompts = (data.canonical_scenes || []).map((s) => ({ scene_id: s.scene_id, required: Boolean(s.requires_image_prompt), purpose: s.requires_image_prompt ? 'reference_frame_or_image_to_video_input' : 'not_required', image_prompt: s.requires_image_prompt ? `${s.canonical_cinematic_prompt} Render a single decisive still frame with no motion blur and no text.` : '', negative_prompt: s.requires_image_prompt ? s.canonical_negative_prompt : '', aspect_ratio: '9:16', continuity_reference: s.continuity_notes || '' }));
return [{ json: { ...data, image_prompts: prompts } }];

// Purpose: Run production QA after the selected model adapter and image prompt stage.
// QA blocks exports if scenes, prompts, voiceover, SRT, or publishing data are incomplete.
const data = $input.first()?.json || {};
const input = data.production_input || {};
const scenes = Array.isArray(data.canonical_scenes) ? data.canonical_scenes : [];
const videoPrompts = Array.isArray(data.video_prompts) ? data.video_prompts : [];
const imagePrompts = Array.isArray(data.image_prompts) ? data.image_prompts : [];
const issues = [];
const warnings = [...(data.validation_warnings || [])];
if (!scenes.length) issues.push('No canonical scenes were generated.');
if (videoPrompts.length !== scenes.length) issues.push('Every canonical scene must have exactly one model-adapted video prompt.');
if (imagePrompts.length !== scenes.length) issues.push('Image prompt alignment does not match canonical scenes.');
if (new Set(scenes.map((s) => s.scene_id)).size !== scenes.length) issues.push('Canonical scene IDs must be unique.');
if (videoPrompts.some((p) => !String(p.prompt || p.text_prompt || p.positive_prompt || '').trim())) issues.push('One or more model prompts are empty.');
if (!String(input.voiceover || '').trim()) issues.push('Voiceover is empty.');
if (!String(input.subtitles_srt || '').includes('-->')) issues.push('SRT is missing or has no timestamp arrow.');
if (!input.publishing_package || !Object.keys(input.publishing_package).length) issues.push('Publishing package is empty.');
const qaScore = Math.max(0, 100 - issues.length * 20 - warnings.length * 2);
return [{ json: { ...data, production_qa: { passed: issues.length === 0, score: qaScore, issues, warnings }, qa_passed: issues.length === 0 } }];

// Purpose: Return a structured production QA failure without exporting misleading artifacts.
// Partial canonical data is retained only for diagnosis.
const data = $input.first()?.json || {};
return [{ json: { workflow: 'AI Health OS Video Generator', version: '1.0', status: 'error', failed_step: 'Production Package QA', model_adapter: data.model_adapter || data.selected_model || '', qa: data.production_qa || {}, error_message: 'Production package did not pass QA.', suggested_action: 'Review QA issues and the source Agent 3–6 outputs, then rerun with the complete Final Report.', partial_scene_count: (data.canonical_scenes || []).length } }];

// Purpose: Assemble the complete production package after QA passes.
// Agent 6 publishing content is preserved exactly and no external generation service is called.
const data = $input.first()?.json || {};
const input = data.production_input || {};
const generatedAt = new Date().toISOString();
const packageData = { workflow: 'AI Health OS Video Generator', version: '1.0', status: 'success', source_workflow: input.source_workflow, source_master_run_id: input.source_master_run_id, model_adapter: data.model_adapter, topic: input.topic, product_name: input.product_name, video_title: input.video_title, hook: input.hook, full_script: input.full_script, canonical_scene_specification_version: data.canonical_scene_specification_version, scenes: data.canonical_scenes || [], video_prompts: data.video_prompts || [], image_prompts: data.image_prompts || [], voiceover: input.voiceover, voiceover_segments: input.voiceover_segments || [], subtitles: input.subtitles || [], subtitles_srt: input.subtitles_srt, publishing_package: input.publishing_package, ...(data.model_adapter === 'runway' ? { generated_video_results: Array.isArray(data.generated_video_results) ? data.generated_video_results : [], runway_execution: data.runway_execution || null } : {}), qa: data.production_qa, generated_at: generatedAt, ready_for_manual_generation: true, disclaimer: 'This workflow prepares prompts and production files only. It does not generate media, call external model APIs, upload content, or publish automatically. Human review is required.' };
return [{ json: { ...data, production_package: packageData } }];

// Purpose: Export the approved package as five named downloadable n8n binary artifacts.
// Files are created in memory; this node does not write to the host filesystem or call external APIs.
const data = $input.first()?.json || {};
const p = data.production_package || {};
function pretty(value) { return JSON.stringify(value, null, 2); }
function binaryFile(content, fileName, mimeType) { return { data: Buffer.from(String(content ?? ''), 'utf8').toString('base64'), mimeType, fileName, fileExtension: fileName.split('.').pop() }; }
const videoJson = pretty({ workflow: p.workflow, version: p.version, model_adapter: p.model_adapter, source_master_run_id: p.source_master_run_id, video_title: p.video_title, canonical_scene_specification_version: p.canonical_scene_specification_version, video_prompts: p.video_prompts, ...(p.model_adapter === 'runway' ? { generated_video_results: p.generated_video_results || [], runway_execution: p.runway_execution || null } : {}) });
const imageJson = pretty({ workflow: p.workflow, version: p.version, source_master_run_id: p.source_master_run_id, video_title: p.video_title, image_prompts: p.image_prompts });
const voiceoverText = [`Title: ${p.video_title || ''}`, '', p.voiceover || '', '', 'Voiceover Segments', ...(p.voiceover_segments || []).map((s) => `${s.segment_number || ''} [${s.start_time_seconds ?? ''}-${s.end_time_seconds ?? ''}s] ${s.voiceover_text || s.text || ''}`)].join('\n');
const md = ['# AI Health OS Video Production Package', '', `- Status: ${p.status}`, `- Model Adapter: ${p.model_adapter}`, `- Source Master Run ID: ${p.source_master_run_id || ''}`, `- Topic: ${p.topic || ''}`, `- Product: ${p.product_name || ''}`, `- Video Title: ${p.video_title || ''}`, `- QA Score: ${p.qa?.score ?? ''}`, '', '## Hook', '', p.hook || '', '', '## Full Script', '', p.full_script || '', '', '## Scene Production Plan', '', ...(p.scenes || []).flatMap((s) => [`### Scene ${s.scene_number}: ${s.scene_id}`, '', `- Duration: ${s.duration_seconds}s`, `- Subject: ${s.subject}`, `- Action: ${s.action}`, `- Environment: ${s.environment}`, `- Camera: ${s.camera?.shot_type || ''}; ${s.camera?.angle || ''}; ${s.camera?.movement || ''}`, `- Canonical Prompt: ${s.canonical_cinematic_prompt}`, `- Negative Prompt: ${s.canonical_negative_prompt}`, '']), '## Model-Adapted Video Prompts', '', '```json', pretty(p.video_prompts || []), '```', '', '## Image Prompts', '', '```json', pretty(p.image_prompts || []), '```', '', ...(p.model_adapter === 'runway' ? ['## Generated Runway Scene Videos', '', '```json', pretty(p.generated_video_results || []), '```', ''] : []), '## Publishing Package', '', '```json', pretty(p.publishing_package || {}), '```', '', '## QA', '', '```json', pretty(p.qa || {}), '```', '', '## Safety Boundary', '', p.disclaimer || ''].join('\n');
const binary = { video_prompts: binaryFile(videoJson, 'video_prompts.json', 'application/json'), image_prompts: binaryFile(imageJson, 'image_prompts.json', 'application/json'), voiceover: binaryFile(voiceoverText, 'voiceover.txt', 'text/plain'), subtitles: binaryFile(p.subtitles_srt || '', 'subtitles.srt', 'application/x-subrip'), production_package: binaryFile(md, 'production_package.md', 'text/markdown') };
return [{ json: { ...p, files: ['video_prompts.json', 'image_prompts.json', 'voiceover.txt', 'subtitles.srt', 'production_package.md'], file_count: 5 }, binary }];

// Purpose: Return the final production package summary and all five binary files to the caller.
// The successful result is ready for human-reviewed generation, not automatic media production.
const item = $input.first() || { json: {}, binary: {} };
const data = item.json || {};
return [{ json: { ...data, total_scenes: (data.scenes || []).length, video_prompt_count: (data.video_prompts || []).length, image_prompt_count: (data.image_prompts || []).filter((p) => p.required).length, qa_passed: Boolean(data.qa?.passed), ready_for_manual_generation: Boolean(data.ready_for_manual_generation), ...(data.model_adapter === 'runway' ? { generated_video_results: Array.isArray(data.generated_video_results) ? data.generated_video_results : [] } : {}), files: data.files || [] }, binary: item.binary || {} }];

// Purpose: Return one consistent error contract for validation, adapter, and production QA failures.
// Error output never claims generation readiness and contains no generated files.
const data = $input.first()?.json || {};
return [{ json: { ...data, status: 'error', ready_for_manual_generation: false, files: [] } }];

// Purpose: Expand Runway-adapted prompts into one API submission item per canonical scene.
// Security: RUNWAY_API_KEY is read only by HTTP Request header expressions and is never added to item JSON.
// TODO(RUNWAY-DOCS): Verify API version, endpoint, model, ratio, duration values, and request field names against current official Runway documentation after deployment.
const data = $input.first()?.json || {};
const supplied = data.raw_input?.runway_config || data.final_report?.runway_config || {};
