const config = {
  base_url: String(supplied.base_url || 'https://api.dev.runwayml.com').replace(/\/$/, ''),
  api_version: String(supplied.api_version || '2024-11-06'),
  generation_endpoint: String(supplied.generation_endpoint || '/v1/text_to_video'),
  task_endpoint: String(supplied.task_endpoint || '/v1/tasks'),
  model: String(supplied.model || 'gen4.5'),
  duration_seconds: num(supplied.duration_seconds, 5, 1, 10),
  aspect_ratio: String(supplied.aspect_ratio || '720:1280'),
  poll_interval_seconds: num(supplied.poll_interval_seconds, 10, 1, 300),
  max_poll_count: Math.floor(num(supplied.max_poll_count, 60, 1, 360)),
  request_timeout_ms: Math.floor(num(supplied.request_timeout_ms, 120000, 5000, 600000)),
  max_submit_retries: Math.floor(num(supplied.max_submit_retries, 3, 0, 10)),
  max_total_wait_seconds: num(supplied.max_total_wait_seconds, 900, 10, 7200)
