const prompts = Array.isArray(data.video_prompts) ? data.video_prompts : [];
return prompts.map((prompt, index) => ({ json: {
  root_data: data,
  scene_id: String(prompt.scene_id || `scene_${String(index + 1).padStart(3, '0')}`),
  scene_index: index,
  runway_config: config,
  poll_count: 0,
  submit_retry_count: 0,
  polling_started_at: new Date().toISOString(),
  request_body: {
    model: config.model,
    promptText: String(prompt.text_prompt || prompt.prompt || prompt.positive_prompt || prompt.canonical_prompt || ''),
    ratio: config.aspect_ratio,
    duration: config.duration_seconds
  }
}, pairedItem: { item: 0 } }));

// Purpose: Capture the Runway task ID while restoring scene_id and polling configuration after HTTP submission.
// TODO(RUNWAY-DOCS): Verify the task identifier and error body fields against the deployed Runway API version.
const response = $input.first()?.json || {};
const request = typeof $ === 'function' ? ($('Prepare Runway Submission Attempt').item?.json || {}) : (response.__request_context || {});
const body = response.body && typeof response.body === 'object' ? response.body : response;
const statusCode = Number(response.statusCode || response.status || (body.id ? 200 : 0));
const jobId = String(body.id || body.taskId || body.task_id || '').trim();
const retryAfter = Number(response.headers?.['retry-after'] || response.headers?.['Retry-After'] || 0);
const accepted = statusCode >= 200 && statusCode < 300 && Boolean(jobId);
const retryable = statusCode === 429 || statusCode >= 500 || statusCode === 0;
return [{ json: { ...request, submit_status_code: statusCode, job_id: jobId, submission_accepted: accepted, submission_retryable: retryable, retry_after_seconds: retryAfter, sanitized_submit_response: { status_code: statusCode, id: jobId, error: accepted ? '' : String(body.error || body.message || `Runway submission returned HTTP ${statusCode || 'unknown'}`) } } }];

// Purpose: Convert a rejected or malformed Runway submission into a scene-level structured result.
// Secrets and request headers are intentionally excluded.
const data = $input.first()?.json || {};
return [{ json: { root_data: data.root_data || {}, runway_scene_result: { scene_id: data.scene_id || '', scene_index: data.scene_index, status: 'failed', stage: 'submit', job_id: data.job_id || '', status_code: data.submit_status_code || 0, error_code: data.submit_status_code === 429 ? 'rate_limited' : 'submission_failed', error_message: data.sanitized_submit_response?.error || 'Runway submission failed.', poll_count: 0, video_url: '', metadata: {} } } }];

// Purpose: Prepare a sanitized task-status request while retaining scene and bounded-polling state.
// TODO(RUNWAY-DOCS): Verify the /v1/tasks/{id} task-status endpoint after deployment.
const data = $input.first()?.json || {};
return [{ json: { ...data, status_request_url: `${data.runway_config.base_url}${data.runway_config.task_endpoint}/${encodeURIComponent(data.job_id)}` } }];

// Purpose: Normalize Runway task states and outputs into provider-independent polling fields.
// TODO(RUNWAY-DOCS): Verify status values and output/video URL fields against the deployed Runway API version.
const response = $input.first()?.json || {};
const state = typeof $ === 'function' ? ($('Prepare Runway Status Request').item?.json || {}) : (response.__request_context || {});
const body = response.body && typeof response.body === 'object' ? response.body : response;
const statusCode = Number(response.statusCode || response.httpStatus || 200);
const rawStatus = String(body.status || body.state || '').trim().toUpperCase();
const completedStates = ['SUCCEEDED', 'SUCCESS', 'COMPLETED'];
const failedStates = ['FAILED', 'CANCELLED', 'CANCELED', 'ERROR'];
const processingStates = ['PENDING', 'THROTTLED', 'RUNNING', 'PROCESSING', 'QUEUED', 'IN_PROGRESS'];
const output = Array.isArray(body.output) ? body.output : (Array.isArray(body.outputs) ? body.outputs : []);
const videoUrl = String(output[0] || body.videoUrl || body.video_url || body.url || '').trim();
const rateLimited = statusCode === 429;
const apiError = statusCode >= 400 && !rateLimited;
return [{ json: { ...state, check_status_code: statusCode, runway_raw_status: rawStatus || (rateLimited ? 'THROTTLED' : 'UNKNOWN'), runway_completed: completedStates.includes(rawStatus) && Boolean(videoUrl), runway_failed: failedStates.includes(rawStatus) || apiError, runway_processing: processingStates.includes(rawStatus) || rateLimited, generated_video_url: videoUrl, retry_after_seconds: Number(response.headers?.['retry-after'] || response.headers?.['Retry-After'] || state.retry_after_seconds || 0), sanitized_status_response: { status_code: statusCode, status: rawStatus, output_count: output.length, error: String(body.failure || body.error || body.message || '') }, task_metadata: { created_at: body.createdAt || body.created_at || '', updated_at: body.updatedAt || body.updated_at || '', progress: body.progress ?? null } } }];

// Purpose: Preserve scene_id and collect the completed Runway video URL and safe task metadata.
// No video is downloaded, uploaded, or published.
const data = $input.first()?.json || {};
return [{ json: { root_data: data.root_data || {}, runway_scene_result: { scene_id: data.scene_id, scene_index: data.scene_index, status: 'completed', stage: 'complete', job_id: data.job_id, status_code: data.check_status_code, poll_count: data.poll_count || 0, video_url: data.generated_video_url, metadata: { provider: 'runway', model: data.runway_config?.model || '', aspect_ratio: data.runway_config?.aspect_ratio || '', duration_seconds: data.runway_config?.duration_seconds || 0, api_status: data.runway_raw_status, ...data.task_metadata } } } }];

// Purpose: Convert a terminal Runway task/API failure into a scene-level structured result.
// API secrets, authorization headers, and full request bodies are never included.
const data = $input.first()?.json || {};
return [{ json: { root_data: data.root_data || {}, runway_scene_result: { scene_id: data.scene_id || '', scene_index: data.scene_index, status: 'failed', stage: 'poll', job_id: data.job_id || '', status_code: data.check_status_code || 0, error_code: data.check_status_code === 429 ? 'rate_limited' : 'generation_failed', error_message: data.sanitized_status_response?.error || `Runway task ended with status ${data.runway_raw_status || 'unknown'}.`, poll_count: data.poll_count || 0, video_url: '', metadata: { api_status: data.runway_raw_status || '' } } } }];

// Purpose: Increment bounded polling state and calculate timeout without changing scene identity.
// Infinite polling is prevented by both max_poll_count and max_total_wait_seconds.
const data = $input.first()?.json || {};
const pollCount = Number(data.poll_count || 0) + 1;
const started = Date.parse(data.polling_started_at || new Date().toISOString());
const elapsedSeconds = Math.max(0, (Date.now() - started) / 1000);
const timedOut = pollCount >= Number(data.runway_config?.max_poll_count || 60) || elapsedSeconds >= Number(data.runway_config?.max_total_wait_seconds || 900);
return [{ json: { ...data, poll_count: pollCount, elapsed_polling_seconds: elapsedSeconds, runway_timed_out: timedOut } }];

// Purpose: Return a deterministic scene-level timeout after configured polling limits are reached.
// The task ID is retained for manual investigation or recovery.
const data = $input.first()?.json || {};
return [{ json: { root_data: data.root_data || {}, runway_scene_result: { scene_id: data.scene_id || '', scene_index: data.scene_index, status: 'timeout', stage: 'poll', job_id: data.job_id || '', status_code: data.check_status_code || 0, error_code: 'poll_timeout', error_message: `Runway task exceeded ${data.poll_count || 0} polls or ${Math.round(data.elapsed_polling_seconds || 0)} seconds.`, poll_count: data.poll_count || 0, video_url: '', metadata: { last_api_status: data.runway_raw_status || '' } } } }];

// Purpose: Assemble all completed, failed, and timed-out Runway scene results in canonical scene order.
// The production package proceeds only when every scene has a generated video URL.
const items = $input.all();
const payloads = items.map((item) => item.json || {});
const root = payloads.find((p) => p.root_data)?.root_data || {};
