// Purpose: Build one structured Runway execution error after all scene outcomes are assembled.
// Sanitized scene errors are returned without secrets, request headers, or API keys.
const data = $input.first()?.json || {};
const execution = data.runway_execution || {};
return [{ json: { workflow: 'AI Health OS Video Generator', version: '1.0', status: 'error', failed_step: 'Runway API Execution', model_adapter: 'runway', error_message: `${execution.failed_scene_count || 0} Runway scene job(s) failed or timed out.`, runway_execution: execution, generated_video_results: data.generated_video_results || [], suggested_action: 'Verify RUNWAY_API_KEY, Runway account credits, API configuration TODOs, task IDs, rate limits, and failed scene messages. No videos were uploaded or published.', ready_for_manual_generation: false, files: [] } }];

// Purpose: Preserve the latest scene and retry state immediately before each submission attempt.
